 "content": "def transform(grid):
    """Rebuild the tiled pattern hidden by the 3-colored band and mark tile coordinates."""
    h, w = len(grid), len(grid[0])
    n = next((k for k in range(1, 31) if k * k + k - 1 == h and k * k + k - 1 == w), None)
    if n is None:
        raise ValueError("expected a square grid tiled with one-cell separators")
    starts = [i * (n + 1) for i in range(n)]

    # Every occupied macro-cell contains a copy of the same n-by-n pattern.
    pattern = None
    for tr in starts:
        for tc in starts:
            tile = [row[tc:tc+n] for row in grid[tr:tr+n]]
            if any(v == 2 for row in tile for v in row):
                pattern = tile
                break
        if pattern is not None:
            break
    if pattern is None:
        raise ValueError("no pattern tile found")

    out = [[0] * w for _ in range(h)]
    for r in range(n):
        for c in range(n):
            if pattern[r][c] == 2:
                tr, tc = starts[r], starts[c]
                for y in range(n):
                    for x in range(n):
                        value = pattern[y][x]
                        if y == r and x == c:
                            value = 8
                        out[tr+y][tc+x] = value
    return out
